CREATE TABLE `investment` (
  `id` int NOT NULL AUTO_INCREMENT,
  `user_id` int NOT NULL,
  `batch_id` varchar(64) DEFAULT NULL,
  `fund_id` int DEFAULT NULL,
  `isin` varchar(20) DEFAULT NULL,
  `transaction_type` varchar(20) NOT NULL,
  `amount` decimal(18,2) NOT NULL,
  `nav` decimal(18,8) DEFAULT NULL,
  `units` decimal(18,6) DEFAULT NULL,
  `date` date NOT NULL,
  `folio_number` varchar(50) DEFAULT NULL,
  `plan_type` varchar(20) DEFAULT NULL,
  `source_file` varchar(255) DEFAULT NULL,
  `registrar` enum('CAMS','Karvy') DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `user_id` (`user_id`),
  KEY `fund_id` (`fund_id`),
  CONSTRAINT `investment_ibfk_1` FOREIGN KEY (`user_id`) REFERENCES `user` (`id`),
  CONSTRAINT `investment_ibfk_2` FOREIGN KEY (`fund_id`) REFERENCES `fund` (`id`)
